import os
import re
import unicodedata
import hashlib
import hmac
import secrets
from pathlib import PurePosixPath
from html import escape as html_escape
from typing import Optional, Dict, Tuple

# Secure document management system
class DocumentStore:
    """Handles secure document storage with path validation and access control."""

    BASE_DIR = '/var/documents/shared'
    ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.docx', '.md', '.csv'}
    MAX_FILENAME_LENGTH = 255
    MAX_PATH_DEPTH = 5

    def __init__(self, secret_key: bytes):
        self._secret = secret_key
        self._access_log: list = []
        self._session_tokens: Dict[str, str] = {}  # token -> username

    def _generate_session_token(self, username: str) -> str:
        """Generate a cryptographically secure session token."""
        token = secrets.token_urlsafe(32)
        self._session_tokens[token] = username
        return token

    def _verify_session(self, token: str) -> Optional[str]:
        """Verify session token and return username."""
        return self._session_tokens.get(token)

    def _compute_file_mac(self, filepath: str, username: str) -> str:
        """Compute HMAC for file integrity verification."""
        msg = f"{filepath}:{username}".encode('utf-8')
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def _check_extension(self, filename: str) -> bool:
        """Validate file extension against allowlist."""
        _, ext = os.path.splitext(filename)
        return ext.lower() in self.ALLOWED_EXTENSIONS

    def _check_path_depth(self, path: str) -> bool:
        """Ensure path doesn't exceed maximum depth."""
        parts = PurePosixPath(path).parts
        return len(parts) <= self.MAX_PATH_DEPTH

    def _contains_traversal_sequences(self, path: str) -> bool:
        """Check for directory traversal patterns."""
        # Check for various traversal patterns
        dangerous_patterns = [
            '..', './', '/.', '~/',
            '%2e', '%2f', '%5c',
            '\\',
        ]
        path_lower = path.lower()
        for pattern in dangerous_patterns:
            if pattern in path_lower:
                return True
        return False

    def _sanitize_path_component(self, component: str) -> str:
        """Remove null bytes and control characters from path component."""
        # Remove null bytes
        component = component.replace('\x00', '')
        # Remove control characters (0x01-0x1f, 0x7f)
        component = ''.join(c for c in component if ord(c) > 0x1f and ord(c) != 0x7f)
        return component

    def _validate_and_resolve_path(self, user_path: str) -> Tuple[bool, str, str]:
        """Core path validation logic.

        Returns (is_valid, resolved_path, error_message)

        Security approach:
        1. Sanitize control characters
        2. Normalize Unicode (NFKC for consistent representation)
        3. Check for traversal sequences
        4. Validate extension and depth
        5. Resolve against base directory
        """
        # Step 1: Remove control characters and null bytes
        cleaned = self._sanitize_path_component(user_path)

        if not cleaned or len(cleaned) > self.MAX_FILENAME_LENGTH:
            return (False, '', 'Invalid filename length')

        # Step 2: Unicode normalization FIRST (before security checks)
        # NFKC normalization ensures consistent character representation
        normalized = unicodedata.normalize('NFKC', cleaned)

        # Step 3: Check for directory traversal AFTER normalization
        if self._contains_traversal_sequences(normalized):
            return (False, '', 'Path traversal detected')

        # Step 4: Validate extension
        if not self._check_extension(normalized):
            return (False, '', 'File extension not allowed')

        # Step 5: Check path depth
        if not self._check_path_depth(normalized):
            return (False, '', 'Path too deep')

        # Step 6: Resolve full path
        full_path = os.path.join(self.BASE_DIR, normalized)
        resolved = os.path.realpath(full_path)

        # Step 7: Verify resolved path is within base directory
        if not resolved.startswith(os.path.realpath(self.BASE_DIR)):
            return (False, '', 'Path resolution outside base directory')

        return (True, resolved, '')

    def retrieve_document(self, session_token: str, document_path: str) -> Dict:
        """Retrieve a document with full security validation.

        Args:
            session_token: Valid session token for authentication
            document_path: Relative path to document within store

        Returns:
            Dict with 'success', 'content' or 'error', and 'metadata'
        """
        # Authentication check
        username = self._verify_session(session_token)
        if not username:
            return {
                'success': False,
                'error': 'Authentication required',
                'content': None
            }

        # Path validation
        is_valid, resolved_path, error = self._validate_and_resolve_path(document_path)

        if not is_valid:
            self._access_log.append({
                'user': username,
                'path': html_escape(document_path),
                'action': 'retrieve',
                'status': 'denied',
                'reason': error
            })
            return {
                'success': False,
                'error': html_escape(error),
                'content': None
            }

        # Read file
        try:
            with open(resolved_path, 'r', encoding='utf-8') as f:
                content = f.read()
        except (IOError, OSError) as e:
            return {
                'success': False,
                'error': 'File not accessible',
                'content': None
            }

        # Log successful access
        self._access_log.append({
            'user': username,
            'path': resolved_path,
            'action': 'retrieve',
            'status': 'granted'
        })

        return {
            'success': True,
            'error': None,
            'content': content,
            'metadata': {
                'path': html_escape(document_path),
                'size': len(content),
                'mac': self._compute_file_mac(resolved_path, username)
            }
        }

    def render_document_listing(self, session_token: str, directory: str = '') -> str:
        """Render HTML listing of documents in a directory."""
        username = self._verify_session(session_token)
        if not username:
            return '<div class="error">Authentication required</div>'

        is_valid, resolved_path, error = self._validate_and_resolve_path(
            directory if directory else '.'
        )

        if not is_valid:
            return f'<div class="error">{html_escape(error)}</div>'

        try:
            entries = os.listdir(resolved_path)
        except OSError:
            return '<div class="error">Directory not accessible</div>'

        html_parts = ['<ul class="file-list">']
        for entry in sorted(entries):
            safe_name = html_escape(entry)
            html_parts.append(f'  <li class="file-entry">{safe_name}</li>')
        html_parts.append('</ul>')

        return '\n'.join(html_parts)
